const express = require("express");
const bodyParser = require("body-parser");

const app = express();

app.use(bodyParser.json());
app.use(express.static("public"));

let students = [];

app.post("/login",(req,res)=>{

const {name,password} = req.body;

if(!name){
return res.json({success:false,message:"Name required"});
}

students.push({name});

res.json({
success:true,
name:name,
schedule:[
"📘 Data Structures Lecture - 10 AM",
"🤖 Artificial Intelligence Lab - 1 PM",
"🧪 Virtual Reality Experiment - 4 PM"
],
progress:75
});

});

app.post("/focus",(req,res)=>{

res.json({
message:"Focus Mode Activated. Notifications blocked."
});

});

app.post("/chat",(req,res)=>{

let msg=req.body.message.toLowerCase();

let reply;

if(msg.includes("stress") || msg.includes("tired")){
reply="Take a deep breath. Try a 2 minute relaxation exercise.";
}
else if(msg.includes("happy")){
reply="That's wonderful! Keep learning and stay motivated.";
}
else{
reply="I'm here to support your learning journey.";
}

res.json({reply});

});

app.listen(3000,()=>{
console.log("Server running on http://localhost:3000");
});